import {initialState,applyCommand,uuid,validateBackup} from './domain.js';
const DEMO='pokerzada-demo-v1',AUTH='pokerzada-auth-v1',CONF='pokerzada-cloud-v1',PENDING='pokerzada-pending-v2';
const read=(storage,key,fallback=null)=>{try{return JSON.parse(storage.getItem(key)||'null')??fallback;}catch{return fallback;}};
export class Repository{
 constructor(){this.mode='none';this.state=null;this.auth=null;this.pending=null;this.generation=0;this.changed=()=>{};this.status=()=>{};this.config=read(localStorage,CONF)||window.POKERZADA_CONFIG||{};}
 startDemo(){this.disconnect();this.mode='demo';this.auth=null;this.pending=null;const saved=read(localStorage,DEMO);this.state=saved?validateBackup(saved):initialState();this.state.account=initialState().account;this.state.accounts=[];this.status('Demonstração • somente neste navegador');return this.state;}
 async connect(config){const u=new URL(config.supabaseUrl);if(u.protocol!=='https:'||!u.hostname.endsWith('.supabase.co'))throw Error('Use a URL HTTPS do seu projeto Supabase.');if(!config.publishableKey||config.publishableKey.startsWith('sb_secret_'))throw Error('Informe somente a chave publicável do projeto.');if(config.publishableKey.startsWith('eyJ')){try{const claims=JSON.parse(atob(config.publishableKey.split('.')[1].replace(/-/g,'+').replace(/_/g,'/')));if(claims.role!=='anon')throw Error();}catch{throw Error('Chave inválida. Nunca use service_role.');}}if(this.config.supabaseUrl!==u.origin){this.disconnect();this.auth=null;sessionStorage.removeItem(AUTH);}this.config={supabaseUrl:u.origin,publishableKey:config.publishableKey};localStorage.setItem(CONF,JSON.stringify(this.config));}
 saveAuth(){sessionStorage.setItem(AUTH,JSON.stringify({project:this.config.supabaseUrl,session:this.auth}));}
 async register(username,password,confirmPassword){return this.request('/functions/v1/poker-auth',{action:'register',username,password,confirmPassword},false);}
 async changePassword(currentPassword,password,confirmPassword){await this.request('/functions/v1/poker-auth',{action:'password',currentPassword,password,confirmPassword});await this.load();}
 async login(username,password){const a=await this.request('/functions/v1/poker-auth',{action:'login',username,password},false);this.auth=a;try{await this.activate();this.saveAuth();}catch(e){this.disconnect();this.auth=null;this.mode='none';this.state=null;sessionStorage.removeItem(AUTH);this.changed();throw e;}}
 async resume(){const saved=read(sessionStorage,AUTH);if(!saved?.session||saved.project!==this.config.supabaseUrl)return false;try{this.auth=saved.session;await this.refreshToken();await this.activate();return true;}catch{this.disconnect();this.auth=null;this.mode='none';this.state=null;sessionStorage.removeItem(AUTH);return false;}}
 get countDraftPrefix(){return 'pokerzada-count-v1:'+this.mode+':'+this.config.supabaseUrl+':'+(this.auth?.user?.id||'demo')+':';}
 countDraft(sid,pid){return read(localStorage,this.countDraftPrefix+sid+':'+pid);}
 saveCountDraft(sid,pid,draft){const key=this.countDraftPrefix+sid+':'+pid;if(draft)localStorage.setItem(key,JSON.stringify(draft));else localStorage.removeItem(key);}
 countDrafts(){const out=[];for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);if(key?.startsWith(this.countDraftPrefix)){const d=read(localStorage,key);if(d)out.push(d);}}return out;}
 get pendingKey(){return PENDING+':'+this.config.supabaseUrl+':'+this.auth?.user?.id;}
 async activate(){this.disconnect();this.mode='cloud';this.state=null;this.pending=read(localStorage,this.pendingKey);await this.load();this.timer=setInterval(()=>this.load().catch(()=>this.status('Sem conexão • última leitura preservada')),10000);this.tokenTimer=setInterval(()=>this.refreshToken().catch(()=>this.status('Sessão expirada • entre novamente')),1800000);this.subscribe();}
 async refreshToken(){if(!this.auth?.refresh_token)return;this.auth=await this.request('/auth/v1/token?grant_type=refresh_token',{refresh_token:this.auth.refresh_token},false);this.saveAuth();}
 async request(path,body,authorize=true){const response=await fetch(this.config.supabaseUrl+path,{method:body?'POST':'GET',headers:{apikey:this.config.publishableKey,'Content-Type':'application/json',...(authorize?{Authorization:'Bearer '+this.auth?.access_token}:{})},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(15000)});const data=await response.json().catch(()=>({}));if(!response.ok)throw Error(data.message||data.error_description||data.msg||'Não foi possível acessar o banco.');return data;}
 async load(){const generation=this.generation;const state=await this.request('/rest/v1/rpc/poker_snapshot',{});if(generation!==this.generation||this.mode!=='cloud')return this.state;if(this.state&&state.revision<this.state.revision)return this.state;const changed=JSON.stringify(this.state)!==JSON.stringify(state);this.state=state;this.status('Sincronizado • '+new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}));if(changed)this.changed();return state;}
 async send(type,payload={},s=null){if(this.pending||this.sending)throw Error('Existe um envio pendente. Confira ou descarte a tentativa antes de continuar.');const signature=JSON.stringify([type,payload,s?.id]);if(signature===this.lastSignature&&Date.now()-this.lastSend<900)throw Error('Aguarde um instante antes de repetir o lançamento.');this.lastSignature=signature;this.lastSend=Date.now();const cmd={id:uuid(),type,payload,sessionId:s?.id||null,expectedRevision:s?.revision??null};return this.execute(cmd);}
 async execute(cmd){if(this.mode==='demo'){const latest=read(localStorage,DEMO)||this.state;latest.account=initialState().account;latest.accounts=[];const next=applyCommand(latest,cmd);localStorage.setItem(DEMO,JSON.stringify(next));this.state=next;this.changed();return next;}
 if(this.mode!=='cloud'||!this.auth)throw Error('Entre como organizador.');if(this.sending)throw Error('Aguarde o envio atual.');this.sending=true;this.pending=cmd;const key=this.pendingKey;try{localStorage.setItem(key,JSON.stringify(cmd));this.status('Salvando…');await this.request('/rest/v1/rpc/poker_command',{command:cmd});await this.load();this.pending=null;localStorage.removeItem(key);this.changed();return this.state;}catch(e){this.status('Envio não confirmado • conferir pendência');throw e;}finally{this.sending=false;}}
 async retry(){if(this.pending)return this.execute(this.pending);}
 async discardPending(){await this.load();localStorage.removeItem(this.pendingKey);this.pending=null;this.changed();}
 subscribe(){try{const ws=new WebSocket(this.config.supabaseUrl.replace('https:','wss:')+'/realtime/v1/websocket?apikey='+encodeURIComponent(this.config.publishableKey)+'&vsn=1.0.0');this.ws=ws;ws.onopen=()=>{ws.send(JSON.stringify({topic:'realtime:pokerzada',event:'phx_join',payload:{config:{postgres_changes:[{event:'*',schema:'public',table:'poker_sessions'},{event:'*',schema:'public',table:'poker_players'}]},access_token:this.auth.access_token},ref:'1'}));this.heartbeat=setInterval(()=>{if(ws.readyState===1)ws.send(JSON.stringify({topic:'phoenix',event:'heartbeat',payload:{},ref:uuid()}));},25000);};ws.onmessage=e=>{try{const data=JSON.parse(e.data);if(data.event==='postgres_changes')this.load().catch(()=>{});}catch{}};}catch{}}
 disconnect(){this.generation++;clearInterval(this.timer);clearInterval(this.tokenTimer);clearInterval(this.heartbeat);this.ws?.close();}
 async logout(){if(this.mode==='cloud')await this.request('/auth/v1/logout',{}).catch(()=>{});this.disconnect();this.auth=null;this.mode='none';this.state=null;sessionStorage.removeItem(AUTH);this.pending=null;}
 resetDemo(){if(this.mode!=='demo')throw Error('Disponível somente na demonstração.');const next=initialState();localStorage.setItem(DEMO,JSON.stringify(next));this.state=next;this.changed();}
 restoreDemo(data){if(this.mode!=='demo')throw Error('Disponível somente na demonstração.');const next=validateBackup(data);next.account=initialState().account;next.accounts=[];localStorage.setItem(DEMO,JSON.stringify(next));this.state=next;this.changed();}
}

